            _q(6, 6, 'basic', 'Việc vừa đọc tên nốt vừa làm kí hiệu bàn tay có lợi ích gì cho học sinh lớp 1?', 'Giúp mắt nhìn, tai nghe và tay cử động cùng lúc, nhớ nhanh độ cao thấp từng nốt nhạc', ['Làm tay bị mỏi không học được hát', 'Để thay thế cho việc mở miệng đọc nốt', 'Để giấu sách nhạc đi'],
               'Học đa giác quan (vận động tay kết hợp âm thanh) là phương pháp rất hiệu quả trong giáo dục âm nhạc hiện đại.', 'Lợi ích kí hiệu bàn tay'),
            _q(6, 7, 'application', 'Cô giáo làm động tác bàn tay lần lượt: Nắm tròn (ngang bụng) -> Duỗi phẳng nằm ngang (ngang ngực) -> Nắm tròn (ngang bụng). Chuỗi nốt bạn cần đọc theo đúng động tác là gì?', 'Đô – Mi – Đô', ['Đô – Rê – Mi', 'Mi – Rê – Đô', 'Rê – Mi – Rê'],
               'Nắm tròn là Đô, bàn tay nằm ngang là Mi, nắm tròn lại là Đô -> Đô – Mi – Đô!', 'Đọc nốt theo kí hiệu tay'),
            _q(6, 8, 'application', 'Bảng dưới đây ghi lại quy ước kí hiệu bàn tay 3 nốt. Dòng nào ghép đúng nốt với tư thế tay?', 'Đô: Nắm tròn; Rê: Chếch lên; Mi: Nằm ngang', ['Đô: Nằm ngang; Rê: Nắm tròn; Mi: Chếch lên', 'Đô: Chếch lên; Rê: Nằm ngang; Mi: Nắm tròn', 'Cả ba nốt đều nắm tròn ở một vị trí'],
               'Ghi nhớ bảng đối chiếu tay giúp em phản xạ cực nhanh khi chơi trò chơi nhìn tay đoán nốt.', 'Bảng kí hiệu tay',
               fig=table_fig('Kí hiệu tay 3 nốt', ['Nốt nhạc', 'Tư thế bàn tay'], [['Đô', 'Nắm tròn, thấp nhất'], ['Rê', 'Duỗi thẳng chếch lên'], ['Mi', 'Duỗi thẳng nằm ngang']])),
            _q(6, 9, 'application', 'Nhìn vào khuông nhạc vẽ 3 nốt Đô – Rê – Mi trên, nốt nào nằm trên đường kẻ thứ nhất (dòng kẻ dưới cùng của 5 dòng kẻ)?', 'Nốt Mi nằm trên dòng kẻ thứ nhất', ['Nốt Đô nằm trên dòng kẻ thứ nhất', 'Nốt Rê nằm trên dòng kẻ thứ nhất', 'Không nốt nào chạm dòng kẻ'],
               'Trong khuông nhạc khóa Sol: Đô có dòng kẻ phụ riêng bên dưới, Rê nằm dưới dòng 1, và Mi nằm đúng dòng 1.', 'Vị trí nốt trên khuông'),
            _q(6, 10, 'application', 'Trong một trò chơi đọc nhạc, nhóm bạn sáng tác câu giai điệu 4 âm: "Đô – Rê – Mi – Mi". Hai nốt cuối "Mi – Mi" được đọc thế nào?', 'Đọc hai lần liên tiếp ở cùng một độ cao bằng nhau của nốt Mi', ['Nốt thứ hai đọc tụt xuống thành Đô', 'Nốt thứ hai đọc cao vọt lên rất cao', 'Bỏ qua không đọc nốt thứ tư'],
               'Hai nốt giống tên nằm ngang hàng thì có cao độ giống hệt nhau (âm đi ngang).', 'Âm đi ngang'),
